insert into public.campaign_day_templates (template_id, day_number, focus, title, description, quest_spec) select id, 1, 'oath', 'Take the Oath', 'Finish your baseline and do 10+ minutes of easy movement of your choice. Start where you are.', '{"primary":{"type":"cardio","allowedActivityTypes":["walking","hiking","running","cycling","swimming","mobility","custom"],"minDurationSeconds":600},"side":[{"type":"mobility","label":"5-minute mobility flow","allowedActivityTypes":["mobility"],"minDurationSeconds":300}],"alternatives":{"noGym":"Walk around the block.","indoorOnly":"March in place or follow a mobility video.","limitedTime":"10 minutes is the whole quest.","mobility":"Gentle seated or standing mobility counts."},"theme":"The Oath"}'::jsonb from public.campaign_templates where key = 'agoge-9' on conflict (template_id, day_number) do nothing;
insert into public.campaign_day_templates (template_id, day_number, focus, title, description, quest_spec) select id, 2, 'strength', 'Full-body technique', '2–3 rounds of squat, push, pull and hinge patterns with easy loads. Focus on form, stop well short of failure.', '{"primary":{"type":"strength","allowedActivityTypes":["strength","obstacle"],"minDurationSeconds":900},"side":[{"type":"mobility","label":"5-minute mobility flow","allowedActivityTypes":["mobility"],"minDurationSeconds":300}],"alternatives":{"noGym":"Bodyweight squats, incline push-ups, band or table rows.","indoorOnly":"Same session at home.","limitedTime":"One round of each pattern, 15 minutes.","mobility":"Use box squats and wall push-ups; skip any painful movement."},"theme":"Strength I"}'::jsonb from public.campaign_templates where key = 'agoge-9' on conflict (template_id, day_number) do nothing;
insert into public.campaign_day_templates (template_id, day_number, focus, title, description, quest_spec) select id, 3, 'cardio', 'Easy aerobic session', '20–40 minutes at a conversational pace (Zone 2): walk, jog, bike or swim.', '{"primary":{"type":"cardio","allowedActivityTypes":["walking","hiking","running","cycling","swimming"],"minDurationSeconds":1200},"side":[{"type":"mobility","label":"5-minute mobility flow","allowedActivityTypes":["mobility"],"minDurationSeconds":300}],"alternatives":{"noGym":"Brisk walk outdoors.","indoorOnly":"Stationary bike, treadmill walk or stairs.","limitedTime":"20 minutes counts.","mobility":"Seated cycling, swimming or water walking if joints need less impact."},"theme":"Endurance I"}'::jsonb from public.campaign_templates where key = 'agoge-9' on conflict (template_id, day_number) do nothing;
insert into public.campaign_day_templates (template_id, day_number, focus, title, description, quest_spec) select id, 4, 'recovery', 'Planned recovery', 'Rest is training. Light mobility or an easy stroll, or simply mark the day as planned rest.', '{"primary":{"type":"recovery","allowedActivityTypes":["recovery","mobility","walking"],"minDurationSeconds":0},"side":[],"alternatives":{"noGym":"Nothing needed.","indoorOnly":"Nothing needed.","limitedTime":"Marking rest is enough.","mobility":"Breathing and gentle range-of-motion work."},"theme":"Recovery"}'::jsonb from public.campaign_templates where key = 'agoge-9' on conflict (template_id, day_number) do nothing;
insert into public.campaign_day_templates (template_id, day_number, focus, title, description, quest_spec) select id, 5, 'strength', 'Controlled strength progress', 'Repeat Strength I and add a small amount of load or a rep or two where it felt easy.', '{"primary":{"type":"strength","allowedActivityTypes":["strength","obstacle"],"minDurationSeconds":1200},"side":[{"type":"cardio","label":"10-minute easy walk","allowedActivityTypes":["walking","hiking"],"minDurationSeconds":600}],"alternatives":{"noGym":"Slow tempo bodyweight work (3 seconds down).","indoorOnly":"Same session at home.","limitedTime":"Two rounds, 15 minutes minimum.","mobility":"Keep ranges comfortable; use supported variations."},"theme":"Strength II"}'::jsonb from public.campaign_templates where key = 'agoge-9' on conflict (template_id, day_number) do nothing;
insert into public.campaign_day_templates (template_id, day_number, focus, title, description, quest_spec) select id, 6, 'cardio', 'Sustainable cardio', '30–50 minutes of easy cardio, a bit longer than Day 3. A hike counts.', '{"primary":{"type":"cardio","allowedActivityTypes":["walking","hiking","running","cycling","swimming"],"minDurationSeconds":1500},"side":[{"type":"mobility","label":"5-minute mobility flow","allowedActivityTypes":["mobility"],"minDurationSeconds":300}],"alternatives":{"noGym":"Long walk or hike.","indoorOnly":"Treadmill or bike.","limitedTime":"25 minutes minimum counts.","mobility":"Low-impact options: bike, pool, elliptical."},"theme":"Endurance II"}'::jsonb from public.campaign_templates where key = 'agoge-9' on conflict (template_id, day_number) do nothing;
insert into public.campaign_day_templates (template_id, day_number, focus, title, description, quest_spec) select id, 7, 'recovery', 'Rest and reflect', 'Planned recovery with an optional Stoic reflection. Ask what was within your control this week.', '{"primary":{"type":"recovery","allowedActivityTypes":["recovery","mobility","walking"],"minDurationSeconds":0},"side":[{"type":"reflection","label":"Evening reflection","allowedActivityTypes":["custom"],"minDurationSeconds":0}],"alternatives":{"noGym":"Nothing needed.","indoorOnly":"Nothing needed.","limitedTime":"Marking rest is enough.","mobility":"Gentle stretching."},"theme":"Recovery & Wisdom"}'::jsonb from public.campaign_templates where key = 'agoge-9' on conflict (template_id, day_number) do nothing;
insert into public.campaign_day_templates (template_id, day_number, focus, title, description, quest_spec) select id, 8, 'trial_prep', 'Comfortable rehearsal', 'Rehearse the skill you chose for tomorrow''s trial at about 70% effort. Confirm your evidence method.', '{"primary":{"type":"skill","allowedActivityTypes":["strength","running","walking","hiking","cycling","swimming","obstacle","custom"],"minDurationSeconds":600},"side":[{"type":"mobility","label":"5-minute mobility flow","allowedActivityTypes":["mobility"],"minDurationSeconds":300}],"alternatives":{"noGym":"Rehearse with what you own.","indoorOnly":"Rehearse indoors.","limitedTime":"10 minutes is enough.","mobility":"Rehearse a modified version of the skill."},"theme":"Trial Preparation"}'::jsonb from public.campaign_templates where key = 'agoge-9' on conflict (template_id, day_number) do nothing;
insert into public.campaign_day_templates (template_id, day_number, focus, title, description, quest_spec) select id, 9, 'trial', 'Your first trial', 'Attempt your chosen assessment and compare it with your baseline. Pass by improving your own mark, with good form and no all-out risk. You can reschedule if you''re not feeling right.', '{"primary":{"type":"skill","allowedActivityTypes":["strength","running","walking","hiking","cycling","swimming","obstacle","custom"],"minDurationSeconds":300},"side":[],"alternatives":{"noGym":"Choose a skill you can test at home.","indoorOnly":"Choose an indoor test.","limitedTime":"Short tests (max push-ups, timed walk) work.","mobility":"Choose a mobility range or a supported-strength test."},"theme":"First Trial"}'::jsonb from public.campaign_templates where key = 'agoge-9' on conflict (template_id, day_number) do nothing;
